import csv, math, statistics, collections
p='ae_ip_termination_by_month.csv'
rows=list(csv.DictReader(open(p)))
print('cols', rows[0].keys() if rows else None)
print('n', len(rows))
for r in rows[:8]: print(r)
# try to identify useful numeric columns
numcols=[]
for c in rows[0].keys():
    try:
        vals=[float(r[c]) for r in rows[:50] if r[c] not in ('','NA','nan')]
        if vals: numcols.append(c)
    except: pass
print('numeric', numcols)
# If there are diagnosis and year/month columns, aggregate
keys=rows[0].keys()
def find(cands):
    for c in cands:
        for k in keys:
            if c.lower() in k.lower(): return k
    return None
diag=find(['diagnosis','diag','condition'])
yr=find(['year'])
mon=find(['month'])
print('diag',diag,'yr',yr,'mon',mon)
if diag and yr:
    agg=collections.defaultdict(lambda: [0,0,0])
    for r in rows:
        d=r.get(diag)
        y=r.get(yr)
        if d is None or y is None: continue
        try:
            rec=float(r.get('recovered') or r.get('Recovered') or 0)
        except: rec=0
        # expected exposures times rate? maybe columns exp and assumed_rate
        exp=None; rate=None
        for k in keys:
            if 'expos' in k.lower():
                try: exp=float(r[k])
                except: exp=None
            if 'assumed' in k.lower() and 'rate' in k.lower():
                try: rate=float(r[k])
                except: rate=None
        if exp is not None and rate is not None:
            expclaims=exp*rate
        else:
            expclaims=None
        if expclaims is not None and expclaims>0:
            agg[(d,y)][0]+=rec
            agg[(d,y)][1]+=expclaims
            agg[(d,y)][2]+=1
    print('diag/year aggregate')
    for k in sorted(agg, key=lambda x:(x[0], x[1])):
        rec,expclaims,n=agg[k]
        if expclaims>50:
            print(k, 'rec', rec, 'exp', round(expclaims,1), 'AE', round(rec/expclaims,3))

